import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Postman API Testing Toolkit","description":"Un workspace Postman con forma de producción: pruebas contractuales CRUD encadenadas, firma HMAC, ejecuciones data-driven, Newman CI con reportes HTML.","frontmatter":{"title":"Postman API Testing Toolkit","description":"Un workspace Postman con forma de producción: pruebas contractuales CRUD encadenadas, firma HMAC, ejecuciones data-driven, Newman CI con reportes HTML."},"headers":[],"relativePath":"es/projects/postman-api-testing-toolkit/index.md","filePath":"es/projects/postman-api-testing-toolkit/index.md"}`),a={name:`es/projects/postman-api-testing-toolkit/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="postman-api-testing-toolkit" tabindex="-1">Postman API Testing Toolkit <a class="header-anchor" href="#postman-api-testing-toolkit" aria-label="Permalink to “Postman API Testing Toolkit”">​</a></h1><p><strong><a href="https://github.com/Godde3s/postman-api-testing-toolkit" target="_blank" rel="noreferrer">Postman API Testing Toolkit</a></strong> responde otro tipo de pregunta de entrevista: <em>¿cómo pruebas una API?</em> No con un GET y un assert de status — con una arquitectura de pruebas por capas que responde tres preguntas distintas: ¿funciona?, ¿cumple su contrato?, ¿falla con gracia?</p><h2 id="lo-que-una-coleccion-verde-realmente-prueba" tabindex="-1">Lo que una colección verde realmente prueba <a class="header-anchor" href="#lo-que-una-coleccion-verde-realmente-prueba" aria-label="Permalink to “Lo que una colección verde realmente prueba”">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Pregunta</th><th>Técnica</th></tr></thead><tbody><tr><td>Smoke</td><td>¿Está vivo?</td><td>Una request por ruta crítica + SLA de latencia</td></tr><tr><td>Contrato</td><td>¿Forma correcta?</td><td>Asserts campo a campo: tipo, presencia, formato</td></tr><tr><td>Funcional</td><td>¿Comportamiento correcto?</td><td>CRUD encadenado vía variables de colección</td></tr><tr><td>Negativo</td><td>¿Errores sanos?</td><td>404s, payloads malformados, valores límite</td></tr><tr><td>Data-driven</td><td>¿Todos los inputs?</td><td>Iteraciones CSV vía Newman</td></tr></tbody></table><h2 id="tecnicas-en-exhibicion" tabindex="-1">Técnicas en exhibición <a class="header-anchor" href="#tecnicas-en-exhibicion" aria-label="Permalink to “Técnicas en exhibición”">​</a></h2><ul><li><strong>Firma HMAC en el sandbox</strong> — un script pre-request calcula <code>HMAC_SHA256(método + ruta + timestamp + bodyHash)</code> con CryptoJS: el patrón anti-replay de toda API seria.</li><li><strong>Payloads dinámicos</strong> — <code>$randomUUID</code> y <code>pm.variables.replaceIn()</code> para datos únicos y trazables en cada corrida.</li><li><strong>CI como canario</strong> — GitHub Actions corre ambas colecciones vía Newman en cada push <em>y</em> a diario, así la deriva de contratos se detecta incluso en semanas sin commits. Reportes HTML como artefactos.</li></ul><div class="tip custom-block"><p class="custom-block-title">Pruébalo</p><p>Importa las colecciones en Postman, o corre headless: <code>newman run collections/rest-crud-api.postman_collection.json -r htmlextra</code> — <a href="https://github.com/Godde3s/postman-api-testing-toolkit" target="_blank" rel="noreferrer">github.com/Godde3s/postman-api-testing-toolkit</a></p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};